// ── PREPARE CONTEXT v3 ────────────────────────────────────────────────────────
// NEW: command detection, language detection, spaced repetition

const triggerData = $('Telegram Trigger').item.json;
const dbRow = $input.item.json;

const messageText = triggerData.message?.text || '';
const studentId   = String(triggerData.message?.from?.id   || '');
const studentName = triggerData.message?.from?.first_name  || 'Student';
const chatId      = triggerData.message?.chat?.id;

const attemptCount    = parseInt(dbRow.attempt_count)  || 0;
const masteryScore    = parseInt(dbRow.mastery_score)  || 0;
const currentTopic    = dbRow.current_topic            || 'Earth Science Basics';
const misconceptions  = dbRow.misconceptions           || '[]';
const completedTopics = dbRow.completed_topics         || '[]';

// ── Command detection ─────────────────────────────────────────────────────────
let isCommand      = false;
let commandType    = null;
let commandResponse = null;

if (messageText.startsWith('/')) {
  const cmd = messageText.split(' ')[0].toLowerCase();

  if (cmd === '/start' || cmd === '/help') {
    isCommand = true;
    commandType = 'start';
    commandResponse = `🌍 Halo, ${studentName}! Welcome to *GeoAI*!\n\nI'm your Socratic tutor for Earth Science, Geography & Disaster Mitigation. I won't just give you answers — I'll guide you to discover them! 🔍\n\n📍 Current topic: *${currentTopic}*\n⭐ Mastery: ${masteryScore}/5\n\nAsk me anything, or use:\n📊 /progress — your stats\n📚 /topic — current topic\n💡 /hint — force a hint now\n🔄 /reset — reset attempt counter`;

  } else if (cmd === '/progress') {
    isCommand = true;
    commandType = 'progress';
    const stars = '⭐'.repeat(masteryScore) + '☆'.repeat(5 - masteryScore);
    let miscList = '\u2022 None detected yet \uD83D�';
    try {
      const arr = typeof misconceptions === 'string' ? JSON.parse(misconceptions) : (misconceptions || []);
      if (arr.length > 0) miscList = arr.map(m => `\u2022 ${m.type.replace(/_/g, ' ')}`).join('\n');
    } catch(e) {}
    let completedList = '\u2022 None yet — keep going!';
    try {
      const arr = typeof completedTopics === 'string' ? JSON.parse(completedTopics) : (completedTopics || []);
      if (arr.length > 0) completedList = arr.map(t => `\u2705 ${t}`).join('\n');
    } catch(e) {}
    commandResponse = `📊 *Progress Report — ${studentName}*\n\n📍 Topic: ${currentTopic}\n${stars} Mastery ${masteryScore}/5\n🔄 Attempt: ${attemptCount}/20\n\n✅ *Completed Topics:*\n${completedList}\n\n🧠 *Tracked Misconceptions:*\n${miscList}\n\n*Terus semangat!* 💪`;

  } else if (cmd === '/topic') {
    isCommand = true;
    commandType = 'topic';
    commandResponse = `📚 Current topic: *${currentTopic}*\n\n⭐ Mastery: ${masteryScore}/5\n\nAsk me anything about this topic! 🌋`;

  } else if (cmd === '/reset') {
    isCommand = true;
    commandType = 'reset';
    commandResponse = `🔄 Reset done, ${studentName}! Your attempt counter is back to zero.\n\nFresh start on *${currentTopic}* — what would you like to explore? 🌍`;

  } else if (cmd === '/hint') {
    // Not a short-circuit — pass through agent with forced hint mode
    commandType = 'hint';
  }
}

// ── Intent classification ─────────────────────────────────────────────────────
const lower = messageText.toLowerCase().trim();
let intent = 'answer_attempt';

if (commandType === 'hint') {
  intent = 'hint_request';
} else if (!isCommand) {
  if (/^(hi|hello|hey|selamat|good morning|good afternoon|halo|hy)\b/i.test(lower)) {
    intent = 'greeting';
  } else if (
    lower.endsWith('?') ||
    /^(what|how|why|when|where|who|is |are |can |does |could |would )/.test(lower)
  ) {
    intent = 'new_question';
  } else if (
    /(clarify|what do you mean|i don.t understand|explain that|elaborate|confused|maksud)/i.test(lower)
  ) {
    intent = 'clarification';
  } else if (
    /(give up|just tell me|i give up|answer please|tell me the answer|just give|langsung kasih|jawab saja|kasih tau)/i.test(lower)
  ) {
    intent = 'bypass_attempt';
  }
}

// ── Language detection ────────────────────────────────────────────────────────
const indonesianMarkers = /\b(apa|bagaimana|mengapa|kenapa|dimana|kapan|siapa|adalah|yang|dan|atau|dengan|untuk|pada|dari|ini|itu|tidak|bisa|akan|sudah|saya|kamu|kami|mereka|jelaskan|sebutkan|tolong|mohon|gimana|emang|sih|dong|ya|nih|loh)\b/i;
const preferredLang = indonesianMarkers.test(messageText) ? 'id' : 'en';

// ── Response mode ─────────────────────────────────────────────────────────────
let responseMode;
if (commandType === 'hint') {
  responseMode = 'hint';
} else if (attemptCount <  5)  responseMode = 'socratic_question';
else if (attemptCount < 10)    responseMode = 'hint';
else if (attemptCount < 15)    responseMode = 'explain_concept';
else if (attemptCount < 20)    responseMode = 'partial_answer';
else                           responseMode = 'full_answer';

// ── Misconception detection ───────────────────────────────────────────────────
const misconceptionPatterns = [
  { pattern: /epicenter.*caus|caus.*epicenter/i,                          type: 'epicenter_confusion',           correction: 'The epicenter is the surface point above the focus. The energy originates at the focus (hypocenter) underground, not the epicenter.' },
  { pattern: /all earthquake.*tsunami|earthquake always.*tsunami/i,       type: 'earthquake_tsunami_assumption', correction: 'Only submarine earthquakes that produce large vertical seafloor displacement generate tsunamis.' },
  { pattern: /volcano.*random|random.*volcano/i,                          type: 'volcano_distribution',         correction: 'Volcanoes are not randomly distributed. They follow tectonic plate boundaries and hotspots.' },
  { pattern: /richter scale (is |are )?use/i,                             type: 'richter_outdated',             correction: 'The Richter scale is largely obsolete for large earthquakes. Scientists now use the Moment Magnitude Scale (Mw).' },
  { pattern: /desert.*always hot|all desert.*hot/i,                       type: 'desert_temperature',           correction: 'Deserts are defined by low precipitation (<250 mm/yr), not temperature. Antarctica and the Gobi are cold deserts.' },
  { pattern: /magma.*same.*lava|lava.*same.*magma|magma and lava (is|are) same/i, type: 'magma_lava_confusion', correction: 'Magma is molten rock underground. Lava is the same material after it erupts onto the surface.' },
  { pattern: /tsunami.*wind|wind.*cause.*tsunami/i,                       type: 'tsunami_wind_cause',           correction: 'Tsunamis are caused by sudden displacement of large volumes of water — not wind.' },
];

let detectedMisconception = null;
for (const mp of misconceptionPatterns) {
  if (mp.pattern.test(messageText)) {
    detectedMisconception = JSON.stringify(mp);
    break;
  }
}

// ── Spaced repetition (resurface old misconceptions ~30% of fresh sessions) ───
let spaceRepetitionCue = null;
if (attemptCount === 0 && intent !== 'greeting' && !isCommand) {
  try {
    const arr = typeof misconceptions === 'string' ? JSON.parse(misconceptions) : (misconceptions || []);
    if (arr.length > 0 && Math.random() < 0.3) {
      spaceRepetitionCue = arr[Math.floor(Math.random() * arr.length)].type.replace(/_/g, ' ');
    }
  } catch(e) {}
}

// ── Difficulty ────────────────────────────────────────────────────────────────
const difficultyLevel = Math.min(masteryScore + 1, 5);

return [{
  json: {
    studentId, studentName, chatId, messageText,
    intent, bypassAttempt: intent === 'bypass_attempt',
    attemptCount, masteryScore, currentTopic,
    misconceptions, completedTopics,
    responseMode, difficultyLevel,
    isFullAnswerMode: responseMode === 'full_answer',
    detectedMisconception,
    isCommand, commandType, commandResponse,
    preferredLang, spaceRepetitionCue,
  }
}];

// ── FORMAT EMBEDDING ─────────────────────────────────────────────────────────
// Converts the OpenAI embedding array to a pgvector-compatible string.

const embedding = $json.data?.[0]?.embedding;

if (!embedding || !Array.isArray(embedding)) {
  // Fallback: return empty context so downstream nodes don't crash
  const ctx = $('Prepare Context').item.json;
  return [{ json: { ...ctx, embeddingStr: null, lessonContext: 'No embedding available. Use general knowledge.' } }];
}

const embeddingStr = '[' + embedding.join(',') + ']';
const ctx = $('Prepare Context').item.json;

return [{
  json: {
    embeddingStr,
    currentTopic: ctx.currentTopic,
  }
}];

// ── FORMAT RAG CONTEXT ───────────────────────────────────────────────────────
// Merges retrieved lesson chunks with Prepare Context data.

const ctx = $('Prepare Context').item.json;
const items = $input.all();

let lessonContext = 'No specific lesson material found for this query. Draw on your general Earth Science knowledge.';

if (items && items.length > 0 && items[0].json && items[0].json.content) {
  const chunks = items
    .filter(item => item.json && item.json.content)
    .map(item => {
      const sim     = item.json.similarity != null ? (parseFloat(item.json.similarity) * 100).toFixed(0) : '?';
      const source  = item.json.source   || 'Curriculum';
      const subtopic = item.json.subtopic || item.json.topic || 'General';
      return `[Source: ${source} | Subtopic: ${subtopic} | Relevance: ${sim}%]\n${item.json.content}`;
    });
  lessonContext = chunks.join('\n\n---\n\n');
}

return [{
  json: {
    ...ctx,
    lessonContext,
  }
}];

// ── GUARDRAIL GATE v3 ─────────────────────────────────────────────────────────
// NEW: topic progression, completed_topics tracking, /reset handling

const agentOutput = $('Orchestrator Agent').item.json.output || '';
const ctx = $('Prepare Context').item.json;

const {
  attemptCount, responseMode, bypassAttempt,
  studentName, masteryScore, studentId,
  currentTopic, misconceptions, chatId,
  detectedMisconception, completedTopics, commandType,
} = ctx;

// ── Anti-spoiler patterns ─────────────────────────────────────────────────────
const spoilerPatterns = [
  /the (?:correct |right )?answer is\s+[^.!?\n]{5,}/i,
  /it(?:'s| is)(?: called)? (?:the )?[A-Z][a-z]{3,}[\s,]/,
  /(?:correct|right|exactly)!\s+[A-Z][a-z]+ (?:is|are) /i,
  /the definition (?:is|of [\w ]+ is)\s+[^.!?\n]{10,}/i,
];

let isSafe = true;
if (responseMode !== 'full_answer') {
  for (const p of spoilerPatterns) {
    if (p.test(agentOutput)) { isSafe = false; break; }
  }
}

let finalResponse = isSafe
  ? agentOutput
  : `\uD83D\uDCAA Semangat, ${studentName}! Let me keep guiding you rather than jumping to the answer.\n\n\uD83D\uDD0D Here is a clue: look back at what you already know about this topic. What single fact might unlock the next step for you?\n\n*(Attempt ${attemptCount} of 20)*`;

// ── Handle /reset command ─────────────────────────────────────────────────────
const isReset = commandType === 'reset';
if (isReset) {
  finalResponse = `\uD83D\uDD04 Done, ${studentName}! Attempt counter is back to zero.\n\nFresh start on *${currentTopic}* — ask me anything! \uD83C\uDF0D`;
}

// ── Mastery leveling ──────────────────────────────────────────────────────────
const successSignals = /\b(correct|well done|excellent|spot on|exactly right|bravo|great answer|nicely done|perfect|bagus|tepat|benar)\b/i;
const shouldLevelUp  = successSignals.test(agentOutput) && responseMode !== 'full_answer' && !isReset;

// ── Attempt counter ───────────────────────────────────────────────────────────
const newAttemptCount = isReset ? 0 : (responseMode === 'full_answer' ? 0 : attemptCount + 1);
const newMasteryScore = shouldLevelUp ? Math.min(masteryScore + 1, 5) : masteryScore;

// ── Topic progression ─────────────────────────────────────────────────────────
const TOPICS_SEQUENCE = [
  'Earth Science Basics', 'Plate Tectonics', 'Earthquakes',
  'Volcanoes', 'Tsunamis', 'Weather & Climate', 'Hydrology', 'Disaster Mitigation',
];

let newCurrentTopic = currentTopic;
let topicAdvanced   = false;

if (newMasteryScore >= 5 && masteryScore < 5) {
  const idx = TOPICS_SEQUENCE.indexOf(currentTopic);
  if (idx >= 0 && idx < TOPICS_SEQUENCE.length - 1) {
    newCurrentTopic = TOPICS_SEQUENCE[idx + 1];
    topicAdvanced   = true;
    finalResponse   = `\uD83C\uDFC6 Luar biasa, ${studentName}! You've fully mastered *${currentTopic}*! \uD83C\uDF93\n\nMoving you to the next topic: *${newCurrentTopic}* \uD83D\uDE80\n\nMastery resets for the new topic — all your progress is saved! Ask me anything about *${newCurrentTopic}* when you're ready. \uD83C\uDF0D`;
  }
}

// ── Completed topics ──────────────────────────────────────────────────────────
let updatedCompletedTopics = completedTopics;
if (topicAdvanced) {
  try {
    const arr = typeof completedTopics === 'string' ? JSON.parse(completedTopics) : (completedTopics || []);
    if (!arr.includes(currentTopic)) arr.push(currentTopic);
    updatedCompletedTopics = JSON.stringify(arr);
  } catch(e) { updatedCompletedTopics = completedTopics; }
}

const finalMasteryScore = topicAdvanced ? 0 : newMasteryScore;

// ── Misconception logging ─────────────────────────────────────────────────────
let updatedMisconceptions = misconceptions;
if (detectedMisconception) {
  try {
    const arr    = typeof misconceptions === 'string' ? JSON.parse(misconceptions) : (misconceptions || []);
    const parsed = JSON.parse(detectedMisconception);
    if (!arr.find(m => m.type === parsed.type)) {
      arr.push({ type: parsed.type, firstSeenAt: new Date().toISOString() });
    }
    updatedMisconceptions = JSON.stringify(arr);
  } catch(e) { updatedMisconceptions = misconceptions; }
}

return [{
  json: {
    studentId, studentName, chatId,
    currentTopic: newCurrentTopic,
    finalResponse, isSafe,
    newAttemptCount,
    newMasteryScore: finalMasteryScore,
    updatedMisconceptions,
    updatedCompletedTopics,
    shouldLevelUp, topicAdvanced,
  }
}];
